#include <iostream>

struct VB1 {
    void display() { std::cout << "VB1" << std::endl; }
};

struct VB2 : virtual VB1 {
    void show() { std::cout << "VB2" << std::endl; }
};

struct Error : VB1, VB2 { // ill-formed due to ambiguity
    void test() {
        display(); // ambiguous: which display() to call?
    }
};

struct Okay : VB2 {
    void test() {
        display(); // unambiguous due to virtual inheritance
    }
};

int main() {
    Okay obj;
    obj.test(); // calls display() from VB1 via virtual inheritance
    return 0;
}
